    },
    {
      "card_ids": ["C47"],
      "claim": "Tranexamic acid, a cyclohexane amino acid, has an absolute oral bioavailability of 46% in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Biotin, a fused bicyclic urea/carboxylic acid, is 100% orally bioavailable in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Gabapentin, a cyclohexane amino acid, has an absolute oral bioavailability of about 60% after a 300 mg oral dose in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C58"],
      "claim": "Phenoxymethylpenicillin, a carboxylic-acid/amide drug, has an oral bioavailability of approximately 50% in normal children, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All high-transfer experimental analogues have measured oral bioavailability at or above 20%, mostly in the 27–100% range, including carboxylic-acid- and amide-containing drugs; therefore the query is predicted high for the F ≥ 20% endpoint.",
